import{_ as a,o as t,c as e,a4 as n}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"DeepSeek Harness：一切皆插件的开源 Agent Harness","description":"","frontmatter":{},"headers":[],"relativePath":"ai-agent/case-studies/deepseek-harness.md","filePath":"ai-agent/case-studies/deepseek-harness.md"}'),i={name:"ai-agent/case-studies/deepseek-harness.md"};function l(o,s,p,r,h,d){return t(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="deepseek-harness-一切皆插件的开源-agent-harness" tabindex="-1">DeepSeek Harness：一切皆插件的开源 Agent Harness <a class="header-anchor" href="#deepseek-harness-一切皆插件的开源-agent-harness" aria-label="Permalink to &quot;DeepSeek Harness：一切皆插件的开源 Agent Harness&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">一句话说清</p><p>DeepSeek Harness（dsh）是 DeepSeek 官方开源的 <strong>Agent 运行框架</strong>——就是 Claude Code、Qoder 这类工具背后那套&quot;让模型真正能干活&quot;的骨架。模型负责聪明，它负责干活。MIT 协议完全免费，2026 年 8 月开源，目前是预览版。</p></div><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>大模型本身只会&quot;生成文字&quot;。让它帮你改代码、跑命令、读文件，需要一整套外部系统配合：</p><ul><li>能执行命令、读写文件的<strong>工具</strong></li><li>记住&quot;刚才干到哪了&quot;的<strong>会话记忆</strong></li><li>决定&quot;哪些操作要问你一声&quot;的<strong>权限</strong></li><li>出错之后怎么<strong>恢复</strong></li></ul><p>这套系统就是 Harness（驾驭工具）。DeepSeek 把这套系统整个开源了，这就是 dsh——官方口号 &quot;Model + Harness = Agent&quot;。</p><h2 id="怎么理解-一切皆插件" tabindex="-1">怎么理解&quot;一切皆插件&quot; <a class="header-anchor" href="#怎么理解-一切皆插件" aria-label="Permalink to &quot;怎么理解&quot;一切皆插件&quot;&quot;">​</a></h2><p>dsh 的核心设计叫 &quot;Everything is a Plugin&quot;（一切都是插件）。</p><p>可以把它想成一台<strong>组装电脑</strong>：CPU、内存、硬盘、显卡都是标准件，你可以换任意一个部件，甚至自己造一个插上去。</p><p>在 dsh 里：</p><ul><li>模型接入是一个插件（想换模型就换插件）</li><li>执行 bash 是一个插件</li><li>读写文件是一个插件</li><li>会话记录是一个插件</li><li>界面（Web UI）也是一个插件</li></ul><p>连&quot;这几个插件怎么组合在一起&quot;本身也是配置（官方叫 profile），有官方预装的组合，也可以自己拼。</p><p>它靠一个叫 Cordis 的插件框架实现：每个插件只做一件事，插件之间通过<strong>事件</strong>通信（比如&quot;模型要调工具了&quot;这个事件，谁感兴趣谁来接），需要别的插件时声明依赖，框架自动排好加载顺序——不用你手工安排谁先启动。</p><h2 id="一次任务是怎么跑起来的" tabindex="-1">一次任务是怎么跑起来的 <a class="header-anchor" href="#一次任务是怎么跑起来的" aria-label="Permalink to &quot;一次任务是怎么跑起来的&quot;">​</a></h2><p>你在 Web UI 里输入一句话，dsh 内部是这样流转的（简化版）：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant 你</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant dsh as dsh 框架</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant 模型 as DeepSeek 模型（远程）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant 工具 as bash/文件等工具（本地）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant 日志 as 会话日志（本地）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  你-&gt;&gt;dsh: 输入任务</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  dsh-&gt;&gt;日志: 记录&quot;用户说了什么&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  dsh-&gt;&gt;模型: 发消息（带上工具清单）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  模型--&gt;&gt;dsh: 决定：先跑个命令看看</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  dsh-&gt;&gt;日志: 记录&quot;模型要调工具&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  dsh-&gt;&gt;工具: 执行命令（在沙箱里）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  工具--&gt;&gt;dsh: 返回结果</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  dsh-&gt;&gt;日志: 记录&quot;工具结果&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  dsh-&gt;&gt;模型: 把结果发给模型，继续</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  模型--&gt;&gt;dsh: 改好文件了，完成</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  dsh-&gt;&gt;日志: 记录结束</span></span></code></pre></div><p>注意一个关键点：<strong>每一步都先记录、再执行</strong>。&quot;模型要调工具&quot;这句话在命令真正执行之前就已经写进日志了。</p><h2 id="三个值得记住的设计" tabindex="-1">三个值得记住的设计 <a class="header-anchor" href="#三个值得记住的设计" aria-label="Permalink to &quot;三个值得记住的设计&quot;">​</a></h2><h3 id="_1-会话记录是-账本-不是聊天记录" tabindex="-1">1. 会话记录是&quot;账本&quot;，不是聊天记录 <a class="header-anchor" href="#_1-会话记录是-账本-不是聊天记录" aria-label="Permalink to &quot;1. 会话记录是&quot;账本&quot;，不是聊天记录&quot;">​</a></h3><p>dsh 把整个交互过程记成一份<strong>只能追加、不能修改</strong>的事件日志（官方叫 Session Log）。模型看到的每一句话、它调的每个工具、每个结果，全部在里面。</p><p>最硬的一条规则是：<strong>&quot;凡是模型见过的，日志里必须能找到&quot;</strong>。聊天历史不是单独存的一份，而是从这个账本里重新算出来的。</p><p>这意味着：任何时刻断电、崩溃，日志都能完整还原对话——包括中途压缩过、分叉过的对话。我们之前聊的 ledger/证据链，它就是最严格的版本。</p><h3 id="_2-模型要调工具-先过-审批流水线" tabindex="-1">2. 模型要调工具，先过&quot;审批流水线&quot; <a class="header-anchor" href="#_2-模型要调工具-先过-审批流水线" aria-label="Permalink to &quot;2. 模型要调工具，先过&quot;审批流水线&quot;&quot;">​</a></h3><p>工具调用不是模型说调就调，中间有层层关卡（全是插件，可增可减）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型说要调工具</span></span>
<span class="line"><span>  → 拦截钩子（可以拒绝，也可以改写请求）</span></span>
<span class="line"><span>  → 权限校验（这个操作允许吗？）</span></span>
<span class="line"><span>  → 需要的话问你审批</span></span>
<span class="line"><span>  → 执行（带超时、重试）</span></span>
<span class="line"><span>  → 结果检查（可以接受、阻断、替换）</span></span>
<span class="line"><span>  → 记录结果</span></span></code></pre></div><p>这个设计正好对应我们之前聊过的 hook 拦截 + gate 校验：<strong>把&quot;靠模型自觉&quot;变成&quot;靠系统把关&quot;</strong>。</p><h3 id="_3-拦截钩子不是只能拦-还能-改" tabindex="-1">3. 拦截钩子不是只能拦，还能&quot;改&quot; <a class="header-anchor" href="#_3-拦截钩子不是只能拦-还能-改" aria-label="Permalink to &quot;3. 拦截钩子不是只能拦，还能&quot;改&quot;&quot;">​</a></h3><p>我们之前规划 hook 时想的是&quot;拦截/放行&quot;。dsh 的钩子更强：它可以<strong>改写</strong>即将执行的流程（比如把项目约定插进上下文），再放行。拒绝是它的一种选择，不是它的全部。</p><h2 id="和我们-harness-计划的对照" tabindex="-1">和我们 Harness 计划的对照 <a class="header-anchor" href="#和我们-harness-计划的对照" aria-label="Permalink to &quot;和我们 Harness 计划的对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>dsh 的做法</th><th>我们计划的对应</th><th>值得学的</th></tr></thead><tbody><tr><td>会话日志（追加式账本）</td><td>ledger / 证据链</td><td>强制&quot;模型可见的必须可回放&quot;，不只是记录</td></tr><tr><td>工具流水线（拦截→审批→执行→检查）</td><td>gate 校验</td><td>关卡分两类：可协作的钩子和必须保序的守卫</td></tr><tr><td>pre-step 钩子</td><td>hook 拦截</td><td>除了拦，还能改写消息</td></tr><tr><td>一切皆插件</td><td>载体降级链</td><td>连&quot;组合方式&quot;本身也是配置</td></tr><tr><td>控制事件与日志事件分开</td><td>控制 / 证据分离</td><td>实时控制可丢，证据不能丢</td></tr></tbody></table><h2 id="值得借鉴的实践" tabindex="-1">值得借鉴的实践 <a class="header-anchor" href="#值得借鉴的实践" aria-label="Permalink to &quot;值得借鉴的实践&quot;">​</a></h2><ol><li><strong>控制与证据分开</strong>：实时控制（钩子、状态）和持久记录（日志）是两套事件系统。控制丢了不致命，证据丢了不行。</li><li><strong>先记录后执行</strong>：工具调用在真正执行前就落日志，审计是默认行为，不是事后补的。</li><li><strong>出错要正交上报</strong>：比如&quot;进程超时&quot;和&quot;退出码 0&quot;是两件事，必须分开报告，不能因为一个吞掉另一个。</li><li><strong>销毁要等安静</strong>：关停系统时，发出杀死信号后要等子进程真正退出，不能留孤儿进程。</li></ol><h2 id="怎么继续学" tabindex="-1">怎么继续学 <a class="header-anchor" href="#怎么继续学" aria-label="Permalink to &quot;怎么继续学&quot;">​</a></h2><ul><li>官方文档（有完整中文版）：<a href="https://deepseek-harness.github.io/deepseek-harness/" target="_blank" rel="noreferrer">https://deepseek-harness.github.io/deepseek-harness/</a></li><li>本地代码 <code>docs/</code> 目录每个文档都有 <code>.zh.md</code> 中文版</li><li>推荐顺序：<code>user/guide</code>（怎么用）→ <code>architecture.zh.md</code>（架构总览）→ 感兴趣再深入</li><li>动手最快：配好 API key 后 <code>npx @deepseek-ai/dsh web</code> 跑起来，边用边看</li></ul>`,34)])])}const c=a(i,[["render",l]]);export{g as __pageData,c as default};
